import { getValueByAccessor } from '../../functions/get-value-by-accessor.js';
import type {
  XYChartColorScale,
  XYChartData,
  XYChartHeatmapSeriesProps,
  XYChartScale,
} from '../../types/xy-chart.js';

export function colorAccessor(
  colorScale: XYChartColorScale,
  seriesProps: XYChartHeatmapSeriesProps,
) {
  return (datum: XYChartData) =>
    colorScale(getValueByAccessor(datum, seriesProps.valueAccessor));
}

export function xAccessor(
  xScale: XYChartScale,
  seriesProps: XYChartHeatmapSeriesProps,
) {
  return (datum) => xScale(getValueByAccessor(datum, seriesProps.x0Accessor));
}

export function yAccessor(
  yScale: XYChartScale,
  seriesProps: XYChartHeatmapSeriesProps,
) {
  return (datum) => yScale(getValueByAccessor(datum, seriesProps.y1Accessor));
}

export function widthAccessor(
  xScale: XYChartScale,
  seriesProps: XYChartHeatmapSeriesProps,
) {
  return (datum) =>
    xScale(getValueByAccessor(datum, seriesProps.x1Accessor)) -
    xScale(getValueByAccessor(datum, seriesProps.x0Accessor));
}

export function heightAccessor(
  yScale: XYChartScale,
  seriesProps: XYChartHeatmapSeriesProps,
) {
  return (datum) =>
    yScale(getValueByAccessor(datum, seriesProps.y0Accessor)) -
    yScale(getValueByAccessor(datum, seriesProps.y1Accessor));
}
